mapper.select:
SELECT  FROM demand_delivery_judgement
WHERE workspace_id = #{workspaceId} AND demand_id = #{demandId}
ORDER BY judged_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE j FROM demand_delivery_judgement j
INNER JOIN demand d ON d.id = j.demand_id AND d.workspace_id = j.workspace_id
WHERE j.workspace_id = #{workspaceId} AND d.req_id = #{reqId}
